What does this program print?

```cpp
#include <memory>
#include <print>

struct Node {
    char id;
    std::shared_ptr<Node> next;
    ~Node() { std::print("{}", id); }
};

int main() {
    {
        auto a = std::make_shared<Node>('a');
        auto b = std::make_shared<Node>('b');
        a->next = b;
    }
    std::print("|");
    {
        auto c = std::make_shared<Node>('c');
        auto d = std::make_shared<Node>('d');
        c->next = d;
        d->next = c;
    }
    std::println("|");
}
```
